-- 1. entity_relationships (PK: parent_entity_id, child_entity_id, relationship_type)
DELETE FROM entity_relationships
WHERE parent_entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map)
AND EXISTS (
  SELECT 1 FROM entity_relationships e2
  JOIN _ma_sep_007_tier1_all_map m ON m.duplicate_id = entity_relationships.parent_entity_id
  WHERE e2.parent_entity_id = m.survivor_id AND e2.child_entity_id = entity_relationships.child_entity_id AND e2.relationship_type = entity_relationships.relationship_type
);
UPDATE entity_relationships
SET parent_entity_id = (SELECT survivor_id FROM _ma_sep_007_tier1_all_map WHERE duplicate_id = entity_relationships.parent_entity_id)
WHERE parent_entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map);
DELETE FROM entity_relationships
WHERE child_entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map)
AND EXISTS (
  SELECT 1 FROM entity_relationships e2
  JOIN _ma_sep_007_tier1_all_map m ON m.duplicate_id = entity_relationships.child_entity_id
  WHERE e2.child_entity_id = m.survivor_id AND e2.parent_entity_id = entity_relationships.parent_entity_id AND e2.relationship_type = entity_relationships.relationship_type
);
UPDATE entity_relationships
SET child_entity_id = (SELECT survivor_id FROM _ma_sep_007_tier1_all_map WHERE duplicate_id = entity_relationships.child_entity_id)
WHERE child_entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map);
DELETE FROM entity_relationships WHERE parent_entity_id = child_entity_id;

-- 2. fund_entity_link (PK: etf_symbol; entity_id not part of PK)
UPDATE fund_entity_link
SET entity_id = (SELECT survivor_id FROM _ma_sep_007_tier1_all_map WHERE duplicate_id = fund_entity_link.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map);

-- 3. instrument_entity_map (PK: instrument_key; entity_id not part of PK)
UPDATE instrument_entity_map
SET entity_id = (SELECT survivor_id FROM _ma_sep_007_tier1_all_map WHERE duplicate_id = instrument_entity_map.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map);

-- 4. entity_exposure_monthly (PK: report_month, entity_id, holder_entity_id)
DELETE FROM entity_exposure_monthly
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map)
AND EXISTS (
  SELECT 1 FROM entity_exposure_monthly e2
  JOIN _ma_sep_007_tier1_all_map m ON m.duplicate_id = entity_exposure_monthly.entity_id
  WHERE e2.entity_id = m.survivor_id AND e2.report_month = entity_exposure_monthly.report_month AND e2.holder_entity_id = entity_exposure_monthly.holder_entity_id
);
UPDATE entity_exposure_monthly
SET entity_id = (SELECT survivor_id FROM _ma_sep_007_tier1_all_map WHERE duplicate_id = entity_exposure_monthly.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map);
-- holder_entity_id: re-run the same 0-affected-rows check done for Tier 2 before trusting this is a no-op

-- 5. fund_exposure_coverage (PK: report_month, holder_entity_id) -- re-confirm 0 affected rows live, same as Tier 2, before skipping

-- 6. entity_enrichment_queue (PK: entity_id itself)
DELETE FROM entity_enrichment_queue
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map)
AND EXISTS (
  SELECT 1 FROM entity_enrichment_queue e2
  JOIN _ma_sep_007_tier1_all_map m ON m.duplicate_id = entity_enrichment_queue.entity_id
  WHERE e2.entity_id = m.survivor_id
);
UPDATE entity_enrichment_queue
SET entity_id = (SELECT survivor_id FROM _ma_sep_007_tier1_all_map WHERE duplicate_id = entity_enrichment_queue.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map);

-- 7. entity_isin_map (PK: isin, lei; entity_id not part of PK)
UPDATE entity_isin_map
SET entity_id = (SELECT survivor_id FROM _ma_sep_007_tier1_all_map WHERE duplicate_id = entity_isin_map.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map);

-- 8. entity_master: apply Tier1b GLEIF names to survivors (Tier1 survivors keep existing name -- no UPDATE needed), then remove repointed loser rows
UPDATE entity_master
SET name = (SELECT new_name FROM _ma_sep_007_tier1b_name_map WHERE survivor_id = entity_master.entity_id)
WHERE entity_id IN (SELECT survivor_id FROM _ma_sep_007_tier1b_name_map WHERE new_name IS NOT NULL);
DELETE FROM entity_master WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_007_tier1_all_map);

-- 9. Drop scratch mapping tables
DROP TABLE _ma_sep_007_tier1_merge_map;
DROP TABLE _ma_sep_007_tier1b_name_map;
DROP TABLE _ma_sep_007_tier1_all_map;